    // SampleContour trait tests

    /// A test implementation of SampleContour for a simple rectangular shape.
    struct TestRectangle {
        width: f64,
        height: f64,
    }

    impl SampleContour for TestRectangle {
        fn sample_contour(&self, sample_distance: f64) -> Result<ContourSet, GeometryError> {
            if sample_distance <= 0.0 {
                return Err(GeometryError::InvalidParameter {
                    parameter: "sample_distance".to_string(),
                    message: "Sample distance must be positive".to_string(),
                });
            }

            let mut contour = Contour::new();

            // Bottom edge (segment 0)
            let bottom_samples = (self.width / sample_distance).ceil() as usize;
            let mut current_distance = 0.0;
            for i in 0..bottom_samples {
                let t1 = (i as f64) / bottom_samples as f64;
                let t2 = ((i + 1) as f64) / bottom_samples as f64;
                let x1 = t1 * self.width;
                let x2 = t2 * self.width;
                let segment_length = x2 - x1;
                contour.add_segment(Segment::new(
                    Point::new(DVec2::new(x1, 0.0), DVec2::new(1.0, 0.0), current_distance),
                    Point::new(
                        DVec2::new(x2, 0.0),
                        DVec2::new(1.0, 0.0),
                        current_distance + segment_length,
                    ),
                    0,
                    i < bottom_samples - 1, // smooth within segment, not at corner
                ));
                current_distance += segment_length;
            }

            // Right edge (segment 1)
            let right_samples = (self.height / sample_distance).ceil() as usize;
            for i in 0..right_samples {
                let t1 = (i as f64) / right_samples as f64;
                let t2 = ((i + 1) as f64) / right_samples as f64;
                let y1 = t1 * self.height;
                let y2 = t2 * self.height;
                let segment_length = y2 - y1;
                contour.add_segment(Segment::new(
                    Point::new(
                        DVec2::new(self.width, y1),
                        DVec2::new(0.0, 1.0),
                        current_distance,
                    ),
                    Point::new(
                        DVec2::new(self.width, y2),
                        DVec2::new(0.0, 1.0),
                        current_distance + segment_length,
                    ),
                    1,
                    i < right_samples - 1, // smooth within segment, not at corner
                ));
                current_distance += segment_length;
            }

            // Top edge (segment 2)
            let top_samples = (self.width / sample_distance).ceil() as usize;
            for i in 0..top_samples {
                let t1 = (i as f64) / top_samples as f64;
                let t2 = ((i + 1) as f64) / top_samples as f64;
                let x1 = self.width - t1 * self.width;
                let x2 = self.width - t2 * self.width;
                let segment_length = (x1 - x2).abs();
                contour.add_segment(Segment::new(
                    Point::new(
                        DVec2::new(x1, self.height),
                        DVec2::new(-1.0, 0.0),
                        current_distance,
                    ),
                    Point::new(
                        DVec2::new(x2, self.height),
                        DVec2::new(-1.0, 0.0),
                        current_distance + segment_length,
                    ),
                    2,
                    i < top_samples - 1, // smooth within segment, not at corner
                ));
                current_distance += segment_length;
            }

            // Left edge (segment 3)
            let left_samples = (self.height / sample_distance).ceil() as usize;
            for i in 0..left_samples {
                let t1 = (i as f64) / left_samples as f64;
                let t2 = ((i + 1) as f64) / left_samples as f64;
                let y1 = self.height - t1 * self.height;
                let y2 = self.height - t2 * self.height;
                let segment_length = (y1 - y2).abs();
                contour.add_segment(Segment::new(
                    Point::new(DVec2::new(0.0, y1), DVec2::new(0.0, -1.0), current_distance),
                    Point::new(
                        DVec2::new(0.0, y2),
                        DVec2::new(0.0, -1.0),
                        current_distance + segment_length,
                    ),
                    3,
                    i < left_samples - 1, // smooth within segment, not at corner
                ));
                current_distance += segment_length;
            }

            let mut contour_set = ContourSet::new();
            contour_set.add_contour(contour);

            Ok(contour_set)
        }
    }

    #[test]
    fn test_sample_contour_trait_rectangle() {
        let rect = TestRectangle {
            width: 10.0,
            height: 5.0,
        };

        let result = rect.sample_contour(2.0);
        assert!(result.is_ok());

        let contour_set = result.unwrap();
        assert_eq!(contour_set.len(), 1);
        assert!(!contour_set.contours[0].is_empty());

        // Verify that we have segments from all 4 edges
        let contour = &contour_set.contours[0];
        let segment_ids: Vec<u32> = contour
            .segments
            .iter()
            .map(|s| s.segment)
            .collect::<std::collections::HashSet<_>>()
            .into_iter()
            .collect();
        assert_eq!(segment_ids.len(), 4); // 4 different segment IDs (0, 1, 2, 3)
    }

